{
  "claims": [
    {
      "claim": "A synthetic rule-based classification dataset of 1,000 instances derived from propositional logic templates is accessible",
      "proposal_excerpt": "We use a synthetic rule-based classification dataset of 1,000 instances derived from propositional logic templates, split into 200 calibration examples for prompt formatting and 800 held-out evaluation test instances.",
      "entity": "synthetic rule-based classification dataset",
      "category": "dataset_access",
      "required_value": "available",
      "essential": true
    },
    {
      "claim": "A frozen open-access large language model via API text access is available for predictions and natural language explanations",
      "proposal_excerpt": "We employ a frozen open-access large language model via API text access to generate predictions and natural language explanations over synthetically perturbed rule-based classification instances.",
      "entity": "frozen open-access large language model",
      "category": "model_access",
      "required_value": "API accessible",
      "essential": true
    },
    {
      "claim": "A 7B parameter open-weight instruction-tuned model is available",
      "proposal_excerpt": "We utilize a zero-shot prompting setup with a 7B parameter open-weight instruction-tuned model running under standard generation configurations.",
      "entity": "7B parameter open-weight instruction-tuned model",
      "category": "model_access",
      "required_value": "7B parameters",
      "essential": true
    },
    {
      "claim": "The target language model can output both a structured classification label and a free-text explanation within a single generation pass",
      "proposal_excerpt": "The target language model can reliably output both a structured classification label and a free-text explanation within a single generation pass.",
      "entity": "target language model",
      "category": "model_capability",
      "required_value": "output structured classification and free-text explanation",
      "essential": true
    }
  ]
}
